+
+  const fields = {
+    'full-name': {
+      input: document.getElementById('full-name'),
+      error: document.getElementById('full-name-error'),
+      validate: (v) => {
+        if (!v.trim()) return 'Please enter your full name.';
+        return '';
+      },
+    },
+    email: {
+      input: document.getElementById('email'),
+      error: document.getElementById('email-error'),
+      validate: (v) => {
+        if (!v.trim()) return 'Please enter your email address.';
+        // Simple, permissive email check.
+        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()))
+          return 'Please enter a valid email address.';
+        return '';
+      },
+    },
+    phone: {
+      input: document.getElementById('phone'),
+      error: document.getElementById('phone-error'),
+      validate: (v) => {
+        if (!v.trim()) return '';
+        if (!/^[+\d][\d\s().-]{6,}$/.test(v.trim()))
+          return 'Please enter a valid phone number.';
+        return '';
+      },
+    },
+  };
+
+  function setError(field, message) {
+    field.error.textContent = message;
+    field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
+  }
+
+  function clearStatus() {
+    status.textContent = '';
+    status.classList.remove('is-error');
+  }
+
+  // Re-validate fields only after the user has interacted with them.
+  Object.values(fields).forEach((field) => {
+    field.input.addEventListener('blur', () => {
+      if (field.input.dataset.touched === 'true') {
+        setError(field, field.validate(field.input.value));
+      }
+    });
+    field.input.addEventListener('input', () => {
+      if (field.input.dataset.touched === 'true') {
+        setError(field, field.validate(field.input.value));
+      }
+      clearStatus();
+    });
+    field.input.addEventListener('blur', () => {
+      field.input.dataset.touched = 'true';
+    });
+  });
+
