+    e.preventDefault();
+    clearStatus();
+
+    let firstInvalid = null;
+    Object.values(fields).forEach((field) => {
+      field.input.dataset.touched = 'true';
+      const msg = field.validate(field.input.value);
+      setError(field, msg);
+      if (msg && !firstInvalid) firstInvalid = field.input;
+    });
